INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_obc-clovek-spolecnost_0','Co je rodina?',ARRAY['Spolek sousedů','Pracovní kolektiv','Třída ve škole','Skupina lidí spojená příbuzenstvím a vzájemnou péčí']::TEXT[],3,'Rodina je základní společenská skupina.',1,ARRAY[]::TEXT[],NULL,0,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_1','Kdo pečuje o dítě v rodině?',ARRAY['Pouze stát','Rodiče nebo jiní zákonní zástupci','Pouze škola','Nikdo']::TEXT[],1,'Rodiče mají vůči dětem práva i povinnosti.',1,ARRAY[]::TEXT[],NULL,1,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_2','Co znamená slušné chování?',ARRAY['Prosadit vždy svou','Respektovat druhé a chovat se ohleduplně','Překřičet druhé','Nevšímat si ostatních']::TEXT[],1,'Slušnost je úcta k ostatním lidem.',1,ARRAY[]::TEXT[],NULL,2,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_3','Jak se nazývá skupina spolužáků ve třídě?',ARRAY['Firma','Třídní kolektiv','Politická strana','Spolek']::TEXT[],1,'Kolektiv je skupina lidí, kteří spolu něco dělají.',1,ARRAY[]::TEXT[],NULL,3,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_4','Co je to šikana?',ARRAY['Hra ve skupině','Soutěž ve škole','Jednorázová hádka kamarádů','Opakované úmyslné ubližování slabšímu']::TEXT[],3,'Šikana je opakovaná agrese vůči oběti.',2,ARRAY[]::TEXT[],NULL,4,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_5','Kam se můžeš obrátit, když jsi svědkem šikany?',ARRAY['Jen na kamarády','Na internetové diskuse','Na učitele, výchovného poradce nebo linku bezpečí','Nikam, jde o soukromou věc']::TEXT[],2,'Pomoc je potřeba vyhledat u dospělých.',2,ARRAY[]::TEXT[],NULL,5,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_6','Jaké je telefonní číslo na tísňovou linku (jednotné evropské)?',ARRAY['155','999','911','112']::TEXT[],3,'112 je jednotné evropské číslo tísňového volání.',2,ARRAY[]::TEXT[],NULL,6,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_7','Jaké číslo platí pro zdravotnickou záchrannou službu v ČR?',ARRAY['158','156','150','155']::TEXT[],3,'155 – záchranná služba, 150 – hasiči, 158 – policie.',2,ARRAY[]::TEXT[],NULL,7,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_8','Co je to tolerance?',ARRAY['Respektování názorů a zvyklostí jiných lidí','Nezájem o druhé','Odmítání odlišností','Souhlas se vším']::TEXT[],0,'Tolerance znamená snášenlivost k odlišnosti.',2,ARRAY[]::TEXT[],NULL,8,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_9','Co je to stereotyp?',ARRAY['Zákon','Zjednodušená a zobecněná představa o skupině lidí','Vědecký poznatek','Nařízení školy']::TEXT[],1,'Stereotypy často vedou k předsudkům.',3,ARRAY[]::TEXT[],NULL,9,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_10','Jaký je rozdíl mezi předsudkem a názorem na základě zkušenosti?',ARRAY['Předsudek je vždy pravdivý','Názor je vždy předsudek','Žádný','Předsudek vzniká bez ověření faktů']::TEXT[],3,'Předsudek je předem vytvořený soud bez znalosti.',3,ARRAY[]::TEXT[],NULL,10,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_11','Co je asertivní komunikace?',ARRAY['Jasně, ale slušně vyjádřit své potřeby a názor','Agresivní prosazování','Mlčení a podřízení se','Ironie a posměch']::TEXT[],0,'Asertivita respektuje sebe i druhé.',3,ARRAY[]::TEXT[],NULL,11,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_12','Která z možností je příklad neverbální komunikace?',ARRAY['Gesto nebo mimika','Dopis','Telefonát','E-mail']::TEXT[],0,'Neverbální komunikace probíhá bez slov.',3,ARRAY[]::TEXT[],NULL,12,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_13','Co je kyberšikana?',ARRAY['Hra na počítači','Sdílení fotek s rodinou','Šikana pomocí internetu a mobilních telefonů','Online výuka']::TEXT[],2,'Kyberšikana probíhá v digitálním prostředí.',3,ARRAY[]::TEXT[],NULL,13,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_14','Co je to sociální skupina?',ARRAY['Jakýkoli dav','Zvíře a jeho majitel','Jeden člověk','Dva a více lidí, kteří mají společný cíl nebo vztah']::TEXT[],3,'Sociální skupina má vazby a pravidla.',3,ARRAY[]::TEXT[],NULL,14,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_15','Která skupina patří mezi primární (blízkou)?',ARRAY['Rodina','Fotbalový stadion','Cestující v tramvaji','Obyvatelé státu']::TEXT[],0,'Primární skupiny mají úzké osobní vztahy.',3,ARRAY[]::TEXT[],NULL,15,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_16','Co je to konflikt?',ARRAY['Střet zájmů nebo názorů dvou či více stran','Společná hra','Vyhrané utkání','Dohoda']::TEXT[],0,'Konflikt lze řešit mediací, kompromisem apod.',4,ARRAY[]::TEXT[],NULL,16,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_17','Jak se nazývá řešení sporu, kdy každá strana něčeho ustoupí?',ARRAY['Boj','Kompromis','Ultimátum','Ignorování']::TEXT[],1,'Kompromis je vzájemný ústupek.',4,ARRAY[]::TEXT[],NULL,17,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_18','Co je to mediace?',ARRAY['Řešení sporu pomocí nestranného prostředníka','Hlasování','Soudní trest','Omluva jen jedné strany']::TEXT[],0,'Mediátor pomáhá stranám dojít k dohodě.',4,ARRAY[]::TEXT[],NULL,18,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_19','Která z těchto hodnot patří mezi základní lidské hodnoty?',ARRAY['Majetek za každou cenu','Úcta ke každému člověku','Moc nade vším','Úspěch bez ohledu na pravidla']::TEXT[],1,'Úcta k lidské důstojnosti je základ společnosti.',4,ARRAY[]::TEXT[],NULL,19,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_20','Jak se nazývá vliv vrstevníků na chování jednotlivce?',ARRAY['Cenzura','Zákon','Školní řád','Tlak skupiny (vrstevnický tlak)']::TEXT[],3,'Skupina může jednotlivce ovlivnit k dobrému i špatnému.',4,ARRAY[]::TEXT[],NULL,20,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_21','Co je to sociální role?',ARRAY['Zákonem daná povinnost','Mzda za práci','Hmotný majetek člověka','Očekávané chování spojené s postavením člověka']::TEXT[],3,'Člověk má zároveň role syna, žáka, kamaráda…',5,ARRAY[]::TEXT[],NULL,21,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_22','Co patří mezi znaky kvalitní informace na internetu?',ARRAY['Je ověřitelná a pochází z důvěryhodného zdroje','Má hodně sdílení','Je napsána velkými písmeny','Je zveřejněna anonymně']::TEXT[],0,'Při hodnocení zdroje sledujeme autora a ověřitelnost.',5,ARRAY[]::TEXT[],NULL,22,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_23','Co je to dezinformace?',ARRAY['Chybná pravopisná forma','Záměrně šířená nepravdivá informace','Rozhovor','Zastaralá zpráva']::TEXT[],1,'Dezinformace mají klamat či manipulovat.',5,ARRAY[]::TEXT[],NULL,23,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-clovek-spolecnost_24','Proč bychom neměli sdílet osobní údaje na sociálních sítích bez rozmyslu?',ARRAY['Protože se zdraží internet','Protože to zakazuje školní řád','Mohou být zneužity a těžko se mažou','Protože jsou nezajímavé']::TEXT[],2,'Informace na internetu se šíří a zůstávají dlouho.',5,ARRAY[]::TEXT[],NULL,24,'c_obc-clovek-spolecnost',NULL,NOW()),
('q_obc-prava-povinnosti_0','Co je zákon?',ARRAY['Rada kamaráda','Doporučení rodičů','Závazné pravidlo přijaté zákonodárným orgánem','Tajný vzkaz']::TEXT[],2,'Zákony musí dodržovat všichni.',1,ARRAY[]::TEXT[],NULL,0,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_1','Který dokument shrnuje základní práva lidí v ČR?',ARRAY['Pracovní smlouva','Školní řád','Listina základních práv a svobod','Jízdní řád']::TEXT[],2,'Listina je součástí ústavního pořádku ČR.',1,ARRAY[]::TEXT[],NULL,1,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_2','Kdo má právo na vzdělání?',ARRAY['Pouze občané města','Každý','Jen bohatí','Jen chlapci']::TEXT[],1,'Právo na vzdělání je základní lidské právo.',1,ARRAY[]::TEXT[],NULL,2,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_3','Ve kterém věku se v ČR stává člověk plnoletým?',ARRAY['V 21 letech','V 18 letech','V 15 letech','V 16 letech']::TEXT[],1,'Plnoletost nastává dovršením 18 let.',1,ARRAY[]::TEXT[],NULL,3,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_4','Jak se nazývá mezinárodní dokument o právech dětí?',ARRAY['Úmluva o právech dítěte','Kjótský protokol','Schengenská dohoda','Magna charta']::TEXT[],0,'Úmluvu přijala OSN v roce 1989.',2,ARRAY[]::TEXT[],NULL,4,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_5','Od kolika let je člověk v ČR trestně odpovědný?',ARRAY['Od 12 let','Od 18 let','Od 15 let','Od 10 let']::TEXT[],2,'Trestní odpovědnost začíná dovršením 15. roku.',2,ARRAY[]::TEXT[],NULL,5,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_6','Kdo rozhoduje o vině a trestu v trestním řízení?',ARRAY['Soud','Zdravotní pojišťovna','Obecní úřad','Škola']::TEXT[],0,'Vinu a trest stanoví nezávislý soud.',2,ARRAY[]::TEXT[],NULL,6,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_7','Která instituce chrání veřejný pořádek a pátrá po pachatelích?',ARRAY['Hasiči','Policie','Záchranná služba','Finanční úřad']::TEXT[],1,'Policie ČR dbá na bezpečnost a pořádek.',2,ARRAY[]::TEXT[],NULL,7,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_8','Jaká je základní povinnost každého občana vůči zákonům?',ARRAY['Hlasovat o nich každý den','Znát je zpaměti','Dodržovat je','Měnit je podle sebe']::TEXT[],2,'Neznalost zákona neomlouvá.',2,ARRAY[]::TEXT[],NULL,8,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_9','Co znamená, že jsou si všichni před zákonem rovni?',ARRAY['Zákony platí pro všechny stejně','Všichni mají stejný plat','Všichni mají stejné povolání','Všichni mají stejný názor']::TEXT[],0,'Rovnost před zákonem je základem právního státu.',3,ARRAY[]::TEXT[],NULL,9,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_10','Jaký je rozdíl mezi přestupkem a trestným činem?',ARRAY['Přestupek je závažnější','Trestný čin je závažnější','Žádný','Přestupky jsou jen pro děti']::TEXT[],1,'Za trestné činy hrozí přísnější trest.',3,ARRAY[]::TEXT[],NULL,10,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_11','Co je to občanský průkaz?',ARRAY['Doklad totožnosti občana ČR','Povolení k pobytu','Řidičský průkaz','Doklad o zaplacení daní']::TEXT[],0,'OP se vydává od 15 let (povinně).',3,ARRAY[]::TEXT[],NULL,11,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_12','Kdo smí uzavřít manželství v ČR?',ARRAY['Osoby od 12 let','Osoby od 18 let','Osoby od 16 bez souhlasu','Osoby od 14 let']::TEXT[],1,'Ve výjimečných případech lze od 16 let se souhlasem soudu.',3,ARRAY[]::TEXT[],NULL,12,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_13','Co je to reklamace?',ARRAY['Vrácení zboží bez důvodu','Nákup zboží','Ceny na slevě','Uplatnění práva z vadného zboží nebo služby']::TEXT[],3,'Prodávající odpovídá za vady zboží.',3,ARRAY[]::TEXT[],NULL,13,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_14','Jak dlouhá je zákonná záruční doba u nového spotřebního zboží v ČR?',ARRAY['12 měsíců','6 měsíců','24 měsíců','36 měsíců']::TEXT[],2,'Zákonná záruka u spotřebitelského zboží je 24 měsíců.',3,ARRAY[]::TEXT[],NULL,14,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_15','Co je to lidská důstojnost?',ARRAY['Bohatství','Ocenění za zásluhy','Hodnota, kterou má každý člověk bez ohledu na původ','Titul']::TEXT[],2,'Důstojnost je neodnímatelná.',4,ARRAY[]::TEXT[],NULL,15,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_16','Která z těchto situací porušuje lidská práva?',ARRAY['Pravidla silničního provozu','Placení daní','Zákaz vzdělání na základě pohlaví','Povinná školní docházka']::TEXT[],2,'Diskriminace pohlaví porušuje rovnost práv.',4,ARRAY[]::TEXT[],NULL,16,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_17','Co je to diskriminace?',ARRAY['Odměňování podle výkonu','Zdvořilost','Rovnost příležitostí','Nerovné zacházení na základě znaku, např. pohlaví či původu']::TEXT[],3,'Diskriminace je zakázaná.',4,ARRAY[]::TEXT[],NULL,17,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_18','Co je smlouva?',ARRAY['Trestní oznámení','Pouze ústní slib','Zákon státu','Dohoda dvou nebo více stran o právech a povinnostech']::TEXT[],3,'Smlouva je závazná pro všechny strany.',4,ARRAY[]::TEXT[],NULL,18,'c_obc-prava-povinnosti',NULL,NOW()),
('q_obc-prava-povinnosti_19','Která instituce hájí práva spotřebitelů v ČR?',ARRAY['Senát','Armáda','Česká obchodní inspekce','Hasičský sbor']::TEXT[],2,'ČOI kontroluje prodejce a řeší stížnosti.',4,ARRAY[]::TEXT[],NULL,19,'c_obc-prava-povinnosti',NULL,NOW()),
